function icon(name,cls=''){return `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;}
const state={plan:{...INITIAL_PLAN},draft:null,selected:'housing',undo:null,choice:'rebook',zoom:1,view:matchMedia('(max-width: 760px)').matches?'list':'map',focused:false};
let toastTimer;
const current=()=>state.draft||state.plan;
const bufferLabel=(day)=>{const delta=18-day;if(delta===0)return 'Ready on arrival day';if(delta>0)return `${delta}-day buffer before arrival`;return `${Math.abs(delta)} day${Math.abs(delta)===1?'':'s'} after arrival`;};
function announce(message){clearTimeout(toastTimer);$('#toast').innerHTML=`${icon('check')}<span>${message}</span>`;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function statusLabel(task,result){if(result.status==='complete')return 'Complete';if(result.status==='conflict')return 'Fixed date · conflict';if(result.status==='blocked')return 'Blocked';if(result.status==='late')return 'After arrival';if(result.status==='review')return 'AI suggestion · review';if(task.id==='housing')return state.draft?'Simulated date':'Next up';if(task.kind==='fixed')return current().rebooked?'Revised appointment':'Fixed appointment';if(task.kind==='milestone')return 'Your milestone';return 'Planned';}
function statusMark(s){return s==='complete'?'✓':s==='conflict'||s==='late'?'!':s==='blocked'?'⊘':s==='review'?'◇':'○';}
function renderGraph(){const plan=current(),dates=calculate(plan),baseline=calculate(state.plan),edges=edgesFor(plan),related=connectedIds(state.selected,plan),changed=new Set(state.draft?impacts(state.plan,plan).map(t=>t.id):[]);
 const paths=edges.map(e=>{const a=TASKS.find(t=>t.id===e.from),b=TASKS.find(t=>t.id===e.to);let d;
 if(e.from==='checkin'&&e.to==='ready'){d=`M${a.x+216} ${a.y+56}H824Q836 ${a.y+56} 836 ${a.y+70}V${b.y+40}Q836 ${b.y+56} 820 ${b.y+56}H${b.x+222}`;}else if(a.x===b.x){const x=a.x+108;d=`M${x} ${a.y+112}V${b.y-8}`;}else{const sx=a.x+216,sy=a.y+56,ex=b.x-5,ey=b.y+56;d=`M${sx} ${sy}C${sx+38} ${sy} ${ex-38} ${ey} ${ex} ${ey}`;}
 const affected=changed.has(e.from)&&!e.suggested,selected=e.from===state.selected||e.to===state.selected;return `<path d="${d}" class="${e.suggested?'suggested':''} ${affected?'affected':''} ${selected?'selected-edge':''}" marker-end="url(#${e.suggested?'arrow-dashed':affected?'arrow-active':'arrow-base'})"/>`;}).join('');
 const nodes=TASKS.map(t=>{const r=dates[t.id],delta=r.day!==null&&baseline[t.id].day!==null?r.day-baseline[t.id].day:0;return `<button id="node-${t.id}" data-task="${t.id}" class="task-node ${state.selected===t.id?'selected':''} ${r.status} ${changed.has(t.id)?'changed':''} ${state.focused&&!related.has(t.id)?'unrelated':''}" style="left:${t.x}px;top:${t.y}px" aria-label="${t.title}, ${statusLabel(t,r)}, ${formatDay(r.day)}${state.selected===t.id?', selected':''}"><span class="node-meta"><span>${statusMark(r.status)}</span>${statusLabel(t,r)}</span><strong>${t.title}</strong><span class="node-footer"><span class="node-date">${r.day===null?'Awaiting resolution':formatDay(r.day)}</span>${delta?`<span class="change-badge">${delta>0?'+':''}${delta}d</span>`:icon(t.icon)}</span>${state.selected===t.id?'<span class="node-port"></span>':''}</button>`;}).join('');
 $('#graph-canvas').innerHTML=`<svg class="connections" viewBox="0 0 860 562" aria-hidden="true"><defs><marker id="arrow-base" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 7 4 0 8" fill="#b2c8bb" stroke="none"/></marker><marker id="arrow-active" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 7 4 0 8" fill="#b97533" stroke="none"/></marker><marker id="arrow-dashed" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 7 4 0 8" fill="#a28cb8" stroke="none"/></marker></defs>${paths}</svg><div class="graph-stage-label" style="left:24px">01 <span>PREPARE</span></div><div class="graph-stage-label" style="left:300px">02 <span>PUT IT TOGETHER</span></div><div class="graph-stage-label" style="left:576px">03 <span>GET READY</span></div>${nodes}`;
 document.querySelectorAll('[data-task]').forEach(el=>el.onclick=()=>selectTask(el.dataset.task));
 $('#steps-list').innerHTML=TASKS.map(t=>`<button class="step-row ${state.selected===t.id?'is-selected':''}" data-list-task="${t.id}">${icon(t.icon)}<span><strong>${t.title}</strong><small>${statusLabel(t,dates[t.id])}</small></span><span class="row-date">${formatDay(dates[t.id].day)}</span>${icon('arrow')}</button>`).join('');
 document.querySelectorAll('[data-list-task]').forEach(el=>el.onclick=()=>selectTask(el.dataset.listTask));fitGraph();}
function selectTask(id){if(!TASKS.some(t=>t.id===id))throw new Error('Unknown task.');state.selected=id;state.focused=true;render();if(innerWidth<=760)$('#inspector').scrollIntoView({behavior:'smooth',block:'start'});}
function fitGraph(){const viewport=$('#graph-viewport'),scale=Math.max(.78,Math.min(1.15,(viewport.clientWidth-28)/860))*state.zoom;$('#graph-canvas').style.zoom=scale;viewport.style.setProperty('--graph-height',`${562*scale+55}px`);}
function renderInspector(){const t=TASKS.find(t=>t.id===state.selected),plan=current(),schedule=calculate(plan),r=schedule[t.id],edges=edgesFor(plan),incoming=edges.filter(e=>e.to===t.id),outgoing=edges.filter(e=>e.from===t.id),changes=state.draft?impacts(state.plan,plan):[];
 $('#inspector').innerHTML=`<div class="inspector-eyebrow">${state.draft?'SCENARIO DETAILS':'STEP DETAILS'}<span>${String(TASKS.indexOf(t)+1).padStart(2,'0')} / 08</span></div><div class="detail-icon">${icon(t.icon)}</div><h2>${t.title}</h2><p class="detail-description">${t.description}</p><div class="detail-date"><span>${t.kind==='fixed'?(plan.rebooked?'Revised slot':'Fixed appointment'):'Planned for'}</span><strong class="${r.status==='conflict'?'text-danger':''}">${formatDay(r.day)}</strong></div>${r.status==='conflict'?`<div class="conflict-note">${icon('info')}<div><strong>This appointment stays put.</strong><p>Your pack would be ready on ${formatDay(schedule.address.day)}. The first compatible check-in is ${formatDay(r.earliest)}.</p></div></div>`:''}${r.status==='blocked'?'<div class="conflict-note"><strong>Resolve the check-in conflict to calculate this milestone.</strong></div>':''}${state.draft&&t.id==='housing'?`<div class="date-control"><label for="housing-date">Housing confirmation date</label><input id="housing-date" type="date" min="2026-10-01" max="2026-10-20" value="2026-10-${String(plan.housingDay).padStart(2,'0')}"><p class="control-hint">Move the date to recalculate every dependent step.</p><div class="date-stepper"><button class="date-step" data-day="-1" aria-label="Move housing date one day earlier">−</button><input id="date-slider" type="range" min="1" max="20" value="${plan.housingDay}" aria-label="Housing confirmation day in October"><button class="date-step" data-day="1" aria-label="Move housing date one day later">+</button></div><div class="date-range-label"><span>01 Oct</span><span>20 Oct</span></div></div>`:''}${state.draft&&t.id==='housing'?`<div class="detail-section impact-list"><h3>${changes.filter(x=>x.id!=='housing').length} DOWNSTREAM EFFECTS</h3>${changes.filter(x=>x.id!=='housing').map(x=>`<button class="impact-item" data-impact="${x.id}"><span>${x.after.status==='conflict'?'!':x.after.status==='blocked'?'⊘':'↳'}</span><span><strong>${x.title}</strong><small>${x.after.status==='conflict'?'Fixed appointment · needs a decision':x.after.status==='blocked'?'Blocked until the conflict is resolved':`${formatDay(x.before.day)} → ${formatDay(x.after.day)}`}</small></span></button>`).join('')||'<p class="empty-small">Choose another date to see what changes.</p>'}</div>`:`${incoming.length?`<div class="detail-section"><h3>DEPENDS ON</h3>${incoming.map(e=>{const a=TASKS.find(x=>x.id===e.from);return `<button class="dependency-button" data-impact="${a.id}">${icon(a.icon)}<span>${a.title}${e.suggested?'<small>Suggested · does not affect dates</small>':`<small>${e.lag?`${e.lag} calendar day${e.lag>1?'s':''} after`:'Ready to use'}</small>`}</span>${icon('arrow')}</button>`;}).join('')}</div>`:''}${outgoing.length?`<div class="detail-section"><h3>THIS UNLOCKS</h3>${outgoing.map(e=>`<button class="unlock-item" data-impact="${e.to}"><span>↳</span>${TASKS.find(x=>x.id===e.to).title}${e.suggested?'<span class="suggestion-tag">?</span>':''}</button>`).join('')}</div>`:!incoming.length?'<div class="detail-section"><h3>INDEPENDENT STEP</h3><p class="empty-small">Changes elsewhere won’t move this task.</p></div>':''}`}
 ${t.id==='bank'&&!plan.bankReviewed?`<div class="assumption-card"><span>${icon('spark')} AI-suggested connection</span><p>The address pack might be useful before comparing banks. This link has no effect until you approve it.</p><div><button id="accept-link" class="button button-outline">Accept link</button><button id="dismiss-link" class="button button-quiet">Dismiss</button></div></div>`:`<div class="evidence-card"><span>${icon('file')} ${t.source}</span><p>“${t.note}”</p><small>${t.sourceType}${t.id==='bank'&&plan.bankReviewed?plan.bankDependency?' · Link accepted':' · Link dismissed':''}</small>${t.id==='bank'&&plan.bankReviewed?'<button class="button button-quiet" id="reopen-link">Review again</button>':''}</div>`}
 <div class="inspector-bottom">${state.draft?`<button class="button button-primary full-width" id="inspector-compare" ${changes.length?'':'disabled'}>${changes.length?(schedule.checkin.status==='conflict'?'Compare 2 recovery plans':'Review this change'):'Choose a new date to continue'} ${changes.length?icon('arrow'):''}</button><p>This is a preview. Your saved plan has not changed.</p>`:t.kind==='complete'?'<p>This step is complete in the sample plan.</p>':'<p>Select any connected step to understand what controls its date.</p>'}</div>`;
 document.querySelectorAll('[data-impact]').forEach(el=>el.onclick=()=>selectTask(el.dataset.impact));
 $('#inspector-compare')?.addEventListener('click',openComparison);$('#reopen-link')?.addEventListener('click',reopenLink);$('#accept-link')?.addEventListener('click',()=>reviewLink(true));$('#dismiss-link')?.addEventListener('click',()=>reviewLink(false));
 $('#housing-date')?.addEventListener('change',e=>{const input=e.target,match=/^2026-10-(\d{2})$/.exec(input.value);if(!match||+match[1]<1||+match[1]>20){input.value=`2026-10-${String(current().housingDay).padStart(2,'0')}`;announce('Choose a date between 1 and 20 October.');return;}setHousingDay(+match[1]);});
 $('#date-slider')?.addEventListener('change',e=>setHousingDay(+e.target.value,'date-slider'));
 document.querySelectorAll('[data-day]').forEach(el=>el.onclick=()=>setHousingDay(Math.max(1,Math.min(20,current().housingDay+Number(el.dataset.day)))));}
function renderTimeline(){const schedule=calculate(current()),base=calculate(state.plan),position=d=>Math.max(0,Math.min(100,(d-1)/30*100));const rows=TASKS.filter(t=>t.kind!=='complete').map(t=>{const r=schedule[t.id],b=base[t.id],diff=!!state.draft&&r.day!==b.day;return `<div class="timeline-row"><button class="timeline-label ${state.selected===t.id?'active':''}" data-timeline="${t.id}">${icon(t.icon)}${t.title}</button><div class="time-grid">${diff&&b.day!==null?`<span class="ghost-date" style="left:${position(b.day)}%" aria-hidden="true"></span>`:''}${r.day!==null?`<button class="time-point ${r.status} ${diff?'shifted':''} ${t.id==='housing'&&state.draft?'draggable-date':''}" data-point="${t.id}" style="left:${position(r.day)}%" aria-label="${t.title}, ${formatDay(r.day)}${t.id==='housing'&&state.draft?', drag to change or use the date field':''}" title="${formatDay(r.day)}"><span>${String(r.day).padStart(2,'0')}</span></button>`:'<span class="blocked-timeline">Waiting for a new check-in plan</span>'}<span class="arrival-line" style="left:${position(18)}%" aria-hidden="true"></span></div></div>`;}).join('');
 $('.timeline-section').innerHTML=`<div class="timeline-heading"><strong>Your October timeline</strong><span>${state.draft?'<i class="ghost-key"></i> Original plan &nbsp; <i class="new-key"></i> Scenario':'Follow a date back to its dependencies'}</span></div><div class="timeline-ruler"><span>OCTOBER 2026</span><div>${[1,6,12,18,24,31].map(d=>`<span style="left:${position(d)}%">${String(d).padStart(2,'0')}</span>`).join('')}</div></div>${rows}<div class="timeline-footnote"><span>${state.draft?'Drag the housing date, or use the date field.':'Select any date to inspect the step.'}</span><span>Arrival: 18 Oct</span></div>`;
 document.querySelectorAll('[data-timeline]').forEach(el=>el.onclick=()=>selectTask(el.dataset.timeline));document.querySelectorAll('[data-point]').forEach(el=>{el.onclick=()=>selectTask(el.dataset.point);if(el.dataset.point==='housing'&&state.draft)bindDateDrag(el);});}
function bindDateDrag(el){el.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();const rect=el.parentElement.getBoundingClientRect();let day=current().housingDay;el.setPointerCapture(e.pointerId);el.classList.add('dragging');const move=event=>{day=Math.max(1,Math.min(20,Math.round((event.clientX-rect.left)/rect.width*30)+1));el.style.left=`${(day-1)/30*100}%`;el.querySelector('span').textContent=String(day).padStart(2,'0');};const end=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',cancel);state.selected='housing';setHousingDay(day);};const cancel=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);render();};el.addEventListener('pointermove',move);el.addEventListener('pointerup',end,{once:true});el.addEventListener('pointercancel',cancel,{once:true});});}
function render(){const focused=document.activeElement;const focusId=focused?.id;const focusAttributes=['data-task','data-list-task','data-impact','data-timeline','data-point','data-day'];const focusKey=focusAttributes.find(k=>focused?.hasAttribute(k));const focusValue=focusKey?focused.getAttribute(focusKey):null;const plan=current(),schedule=calculate(plan),changes=state.draft?impacts(state.plan,plan):[],conflict=schedule.checkin.status==='conflict',late=schedule.ready.status==='late',readyDay=schedule.ready.day,buffer=readyDay===null?null:18-readyDay;$('#plan-health').textContent=conflict?'Check-in conflict':late?'Plan finishes after arrival':state.draft?(changes.length?'Scenario stays on track':'Choose a new date'):state.undo?'Plan updated':'On track';$('#plan-summary').textContent=conflict?`${changes.filter(x=>x.id!=='housing').length} downstream effects · fixed check-in stays ${formatDay(plan.appointmentDay)}`:late?`Ready ${formatDay(readyDay)} · ${bufferLabel(readyDay)}`:`Ready ${formatDay(readyDay)} · ${bufferLabel(readyDay)}${plan.bankReviewed?'':' · 1 link to review'}`;$('.plan-overview').classList.toggle('warning',conflict||late);$('.overview-check').textContent=conflict||late?'!':'✓';$('#simulate-button').innerHTML=state.draft?`${icon('close')} Reset scenario`:`${icon('spark')} Try a 7-day housing delay`;$('#simulate-button').classList.toggle('is-simulating',!!state.draft);$('#custom-date-button').hidden=!!state.draft;$('#undo-button').hidden=!state.undo;$('#simulation-banner').hidden=!state.draft;if(state.draft){$('#simulation-caption').textContent=`Housing confirmation: ${formatDay(state.plan.housingDay)} → ${formatDay(plan.housingDay)}`;$('#banner-compare').textContent=changes.length?(conflict?'2 · Compare recovery plans':'2 · Review change'):'Choose a new date';$('#banner-compare').disabled=!changes.length;}renderGraph();renderInspector();renderTimeline();$('.timeline-section').hidden=!state.draft&&!state.undo;$('#steps-list').hidden=state.view!=='list';$('#graph-viewport').hidden=state.view!=='map';document.querySelectorAll('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===state.view);el.setAttribute('aria-pressed',String(el.dataset.view===state.view));});if(state.view==='map')fitGraph();const restore=focusId?document.getElementById(focusId):focusKey?document.querySelector(`[${focusKey}="${focusValue}"]`):null;if(restore&&!restore.hidden)restore.focus({preventScroll:true});else if(focusId==='accept-link'||focusId==='dismiss-link')$('#node-bank')?.focus({preventScroll:true});}
function startSimulation(day){state.draft={...state.plan,housingDay:day??Math.min(20,state.plan.housingDay+7)};validatePlan(state.draft);state.selected='housing';state.focused=false;render();announce('Simulation started. Your plan has not changed.');if(innerWidth<=760)$('#inspector').scrollIntoView({behavior:'smooth'});}
function startCustomSimulation(){state.draft={...state.plan};state.selected='housing';state.focused=false;render();$('#housing-date')?.focus({preventScroll:true});announce('Choose a housing confirmation date to explore.');if(innerWidth<=760)$('#inspector').scrollIntoView({behavior:'smooth',block:'start'});}
function setHousingDay(day,restore){if(!Number.isInteger(day)||day<1||day>20)throw new Error('Housing date must be an integer from 1 to 20 October.');if(!state.draft)startSimulation(day);else{state.draft.housingDay=day;render();}if(restore)$('#'+restore)?.focus({preventScroll:true});}
function cancelSimulation(){state.draft=null;render();announce('Scenario discarded. Your plan is unchanged.');}
function reviewLink(accepted){if(state.draft){state.draft.bankDependency=accepted;state.draft.bankReviewed=true;}else{state.undo={...state.plan};state.plan={...state.plan,bankDependency:accepted,bankReviewed:true};}render();announce(accepted?'Connection accepted. Banking now follows the address pack.':'Connection dismissed. Banking stays independent.');}
function reopenLink(){if(state.draft){state.draft.bankDependency=false;state.draft.bankReviewed=false;}else{state.undo={...state.plan};state.plan={...state.plan,bankDependency:false,bankReviewed:false};}render();$('#accept-link')?.focus({preventScroll:true});announce('Connection reopened as a suggestion. It no longer changes dates.');}
function undo(){if(!state.undo)return;state.plan={...state.undo};state.undo=null;state.draft=null;state.selected='housing';state.focused=false;render();$('#simulate-button').focus({preventScroll:true});announce('Previous plan restored.');}
function showDialog(html,wide=false){const root=$('#overlay-root');root.innerHTML=`<dialog class="dialog ${wide?'dialog-wide':''}" aria-labelledby="dialog-title"><button class="dialog-close icon-button" aria-label="Close dialog">${icon('close')}</button>${html}</dialog>`;const dialog=root.querySelector('dialog');dialog.showModal();dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});return dialog;}
function openComparison(){if(!state.draft)return;const conflicted=calculate(state.draft).checkin.status==='conflict',options=conflicted?recoveries(state.draft):[{id:'keep',title:'Use the simulated date',label:'Updated plan',description:'Keep the new housing date and every dependent date shown in the preview.',assumption:'Updates this demo plan only.',plan:{...state.draft}}];state.choice=conflicted?null:options[0].id;
const dialog=showDialog(`<div class="dialog-kicker">${icon('graph')} 2 · CHOOSE A RESPONSE</div><h2 id="dialog-title">${conflicted?'Choose a recovery plan':'Review the updated plan'}</h2><p class="dialog-intro">${conflicted?'Both options resolve the conflict. Compare what each requires and how much time remains before arrival.':'Review the outcome before applying this scenario.'}</p><div class="recovery-options">${options.map(o=>{const dates=calculate(o.plan),selected=state.choice===o.id;return `<label class="recovery-option ${selected?'chosen':''}"><input type="radio" name="recovery" value="${o.id}" ${selected?'checked':''}><span class="option-topline"><span>${o.label}</span><span class="radio-mark"></span></span><strong>${o.title}</strong><p>${o.description}</p><div class="outcome-chip ${dates.ready.day>18?'late':''}">${bufferLabel(dates.ready.day)}</div><dl><div><dt>Housing confirmed</dt><dd>${formatDay(o.plan.housingDay)}</dd></div><div><dt>Office check-in</dt><dd>${formatDay(o.plan.appointmentDay)}</dd></div><div><dt>Ready</dt><dd class="${dates.ready.day>18?'text-danger':'text-green'}">${formatDay(dates.ready.day)}</dd></div></dl><div class="option-assumption">${icon('info')}<span>${o.assumption}</span></div></label>`;}).join('')}</div><div id="change-review"></div><p class="decision-note">This changes the demo plan only. It does not update a booking or contact anyone.</p><div class="dialog-footer"><span id="apply-summary">Select an option to continue.</span><button class="button button-primary" id="apply-plan" disabled>Choose an option</button></div>`,true);
const update=()=>{const option=options.find(o=>o.id===state.choice);dialog.querySelectorAll('.recovery-option').forEach(el=>el.classList.toggle('chosen',el.querySelector('input').value===state.choice));if(!option){$('#change-review').innerHTML='<div class="comparison-prompt">Choose an option above to see its exact changes.</div>';$('#apply-plan').disabled=true;return;}const changes=impacts(state.plan,option.plan),dates=calculate(option.plan),optionName=state.choice==='rebook'?'option A':state.choice==='earlier'?'option B':'this plan';$('#change-review').innerHTML=`<div class="change-review-title"><strong>${changes.length} steps will change</strong><span>BEFORE <span>→</span> AFTER</span></div>${changes.map(t=>`<div class="review-row"><span>${t.title}</span><span><del>${t.id==='bank'&&t.before.day===t.after.day?'Suggested link':formatDay(t.before.day)}</del>${icon('arrow')}<strong>${t.id==='bank'&&t.before.day===t.after.day?(option.plan.bankDependency?'Accepted':'Dismissed'):formatDay(t.after.day)}</strong></span></div>`).join('')||'<p class="empty-small">No dates will change.</p>'}`;$('#apply-summary').textContent=bufferLabel(dates.ready.day);$('#apply-plan').disabled=false;$('#apply-plan').innerHTML=`Apply ${optionName} ${icon('arrow')}`;};
dialog.querySelectorAll('[name="recovery"]').forEach(el=>el.onchange=()=>{state.choice=el.value;update();});$('#apply-plan').onclick=()=>{const option=options.find(o=>o.id===state.choice);if(!option)return;const ready=calculate(option.plan).ready.day;state.undo={...state.plan};state.plan={...option.plan};state.draft=null;state.selected='housing';state.focused=false;dialog.close();render();$('#undo-button').focus({preventScroll:true});announce(`Plan updated. Ready ${formatDay(ready)} — ${bufferLabel(ready).toLowerCase()}.`);};update();}
function showAbout(){showDialog(`<div class="dialog-kicker">${icon('graph')} WHY MOVEGRAPH</div><h2 id="dialog-title">Seven cities taught me to stop treating a move like a checklist.</h2><p class="dialog-intro">A list shows what is due. A dependency map shows what will break when one date slips—and where a person still needs to make the call.</p><div class="about-facts"><p><strong>Personal starting point.</strong> MoveGraph comes from Hayk’s experience living in seven cities over four years. The Berlin dates and notes are an illustrative scenario, not official relocation requirements.</p><p><strong>Design judgment.</strong> Flexible dates recalculate. Fixed commitments never move silently. AI-suggested links remain inactive until a person accepts them, and every applied plan can be undone.</p><p><strong>How AI contributed.</strong> AI helped structure the sample scenario, surface edge cases, and critique the interaction. The dates shown here come from visible local rules; no live model or external booking is connected.</p><p><strong>Prototype boundary.</strong> This build focuses on changing one high-leverage date. A full version would let people add a step by defining whether it is fixed or flexible, what it depends on, and how much buffer it needs.</p></div><button class="button button-primary" id="about-done">Back to the plan ${icon('arrow')}</button>`);$('#about-done').onclick=()=>document.querySelector('dialog').close();}
$('.surface-toolbar').innerHTML=`<div class="view-title">${icon('graph')} Dependency map</div><div class="view-switch" aria-label="Plan presentation"><button data-view="map" class="active" aria-pressed="true">Map</button><button data-view="list" aria-pressed="false">Steps</button></div>`;
$('#graph-viewport').insertAdjacentHTML('afterend','<div id="steps-list" class="steps-list" hidden></div>');$('.graph-legend').innerHTML='<span><i class="legend-line"></i> Accepted dependency</span><span><i class="legend-line dotted"></i> AI suggestion</span><span><i class="legend-fixed"></i> Fixed dates move only when you choose</span>';
$('.workspace').insertAdjacentHTML('beforebegin',`<div id="simulation-banner" class="simulation-banner" hidden><div>${icon('spark')}<strong>1 · DELAY</strong><span id="simulation-caption"></span></div><div><button class="button button-quiet" id="discard-simulation">Reset</button><button class="button button-primary" id="banner-compare">2 · Compare recovery plans</button></div></div>`);
$('#simulate-button').insertAdjacentHTML('beforebegin',`<button class="button button-quiet" id="undo-button" hidden>${icon('undo')} Undo change</button><button class="button button-outline" id="custom-date-button">Choose a date</button>`);const actions=document.createElement('div');actions.className='heading-actions';actions.append($('#undo-button'),$('#custom-date-button'),$('#simulate-button'));$('.page-heading').append(actions);
$('#simulate-button').onclick=()=>state.draft?cancelSimulation():startSimulation();$('#custom-date-button').onclick=startCustomSimulation;$('#about-button').onclick=showAbout;$('#footer-about').onclick=showAbout;$('#undo-button').onclick=undo;$('#discard-simulation').onclick=cancelSimulation;$('#banner-compare').onclick=openComparison;document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{state.view=el.dataset.view;render();});window.addEventListener('resize',fitGraph);render();
const context=document.modelContext;
if(context?.registerTool){const controller=new AbortController(),snapshot=()=>({plan:{...state.plan},simulation:state.draft?{...state.draft}:null,selectedTask:state.selected,schedule:calculate(current())}),definitions=[
 {name:'read_move_plan',title:'Read move plan',description:'Read the saved plan, staged simulation, and calculated dates. Does not change the plan.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>snapshot()},
 {name:'stage_housing_change',title:'Simulate housing confirmation date',description:'Start or update a housing date simulation for October 2026. Does not apply it to the saved plan.',inputSchema:{type:'object',properties:{day:{type:'integer',minimum:1,maximum:20}},required:['day'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='day')||!Number.isInteger(input.day)||input.day<1||input.day>20)throw new Error('Provide an integer day from 1 to 20.');setHousingDay(input.day);return snapshot();}},
 {name:'inspect_move_step',title:'Inspect a move step',description:'Select a step and show its dependencies and evidence in the detail panel.',inputSchema:{type:'object',properties:{taskId:{type:'string',enum:TASKS.map(t=>t.id)}},required:['taskId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='taskId'))throw new Error('Provide a taskId.');selectTask(input.taskId);return snapshot();}},
 {name:'discard_move_simulation',title:'Discard simulation',description:'Discard the staged simulation and restore the saved plan in the interface.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{cancelSimulation();return snapshot();}}
 ];for(const tool of definitions){try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
